import { useEffect, useMemo, useState } from "react";
import { motion, AnimatePresence, useReducedMotion } from "motion/react";
import { ShieldCheck, TrendingUp, LogOut, Check, EyeOff, Users, AlertTriangle, RefreshCw, MapPin } from "lucide-react";
import type { AppHandle } from "@app/kit/primitives";

type R = Record<string, unknown>;
type Props = { app?: AppHandle; initialTab?: string };

const SERIF = "'Iowan Old Style','Palatino Linotype',Palatino,'Book Antiqua',Georgia,serif";
const SANS = "ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif";
const EASE = [0.22, 1, 0.36, 1] as const;
const GLOBAL = "body{transition-timing-function:cubic-bezier(0.22,1,0.36,1)}::selection{background:#EAD9C6;color:#2B2420}";
const CARD = "rounded-2xl bg-white shadow-[0_1px_2px_rgba(60,40,20,0.05),0_12px_28px_-18px_rgba(60,40,20,0.3)]";
const BTN = "inline-flex h-11 items-center justify-center gap-2 rounded-full bg-[#8A5A36] px-5 text-[15px] font-medium text-white transition-colors duration-200 hover:bg-[#774C2C] focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#8A5A36] disabled:opacity-60";
const GHOST = "inline-flex h-11 items-center justify-center gap-2 rounded-full border border-[#D9CBB9] bg-white px-5 text-[15px] font-medium text-[#2B2420] transition-colors duration-200 hover:border-[#8A5A36] disabled:opacity-60";
const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const STATUS = ["placed", "paid", "shipped", "delivered"];
const STATUS_LABEL: Record<string, string> = { placed: "Awaiting payment", paid: "To ship", shipped: "Shipped", delivered: "Delivered" };
const STATUS_TONE: Record<string, [string, string]> = { placed: ["#F3EBE0", "#6B4A2A"], paid: ["#F6E7C9", "#6E5114"], shipped: ["#E7EBE3", "#3F4D39"], delivered: ["#EDE7E1", "#5E5145"] };

const s = (r: R | undefined, k: string): string => (r && r[k] != null ? String(r[k]) : "");
const n = (r: R | undefined, k: string): number => (r ? Number(r[k]) || 0 : 0);
const money = (v: number) => "$" + Math.round(v).toLocaleString("en-US");
const cap = (t: string) => t.charAt(0).toUpperCase() + t.slice(1);
const day = (iso: string) => { const d = iso.slice(0, 10).split("-"); return d.length < 3 ? "" : Number(d[2]) + " " + (MONTHS[Number(d[1]) - 1] || ""); };

function Status({ st }: { st: string }) {
  const [bg, fg] = STATUS_TONE[st] || ["#EDE7E1", "#5E5145"];
  return <span className="inline-flex shrink-0 rounded-full px-2.5 py-1 text-[12px] font-medium" style={{ background: bg, color: fg }}>{STATUS_LABEL[st] || cap(st)}</span>;
}

export default function AdminConsole({ app, initialTab }: Props) {
  const reduce = useReducedMotion();
  const [tab, setTab] = useState(initialTab === "sales" ? "sales" : "approvals");
  const [toast, setToast] = useState<{ text: string; bad?: boolean } | null>(null);
  const [busy, setBusy] = useState("");
  const [decided, setDecided] = useState<{ id: string; title: string; status: string }[]>([]);
  const [failed, setFailed] = useState(false);
  const [retry, setRetry] = useState(0);
  useEffect(() => { if (!toast) return; const t = setTimeout(() => setToast(null), 3200); return () => clearTimeout(t); }, [toast]);
  useEffect(() => {
    if (!app) return;
    let live = true;
    setFailed(false);
    app.query("product", { limit: 1 }).catch(() => { if (live) setFailed(true); });
    return () => { live = false; };
  }, [app, retry]);

  const products = (app?.rows("product") ?? []) as R[];
  const sellers = (app?.rows("seller") ?? []) as R[];
  const orders = (app?.rows("order") ?? []) as R[];
  const buyers = (app?.rows("buyer") ?? []) as R[];
  const loading = app?.loading("product") ?? false;
  const seller = (id: string) => sellers.find((x) => s(x, "id") === id);
  const sellerName = (id: string) => s(seller(id), "shop_name") || "Maker";
  const buyerName = (id: string) => s(buyers.find((b) => s(b, "id") === id), "name") || "Customer";
  const pending = products.filter((p) => s(p, "status") === "pending");
  const live = products.filter((p) => s(p, "status") === "approved").length;
  const hidden = products.filter((p) => s(p, "status") === "hidden").length;
  const paidOrders = orders.filter((o) => s(o, "status") !== "placed");
  const gmv = paidOrders.reduce((a, o) => a + n(o, "total"), 0);
  const avg = paidOrders.length ? gmv / paidOrders.length : 0;
  const bySeller = useMemo(() => {
    const m: Record<string, number> = {};
    for (const o of paidOrders) m[s(o, "seller_id")] = (m[s(o, "seller_id")] || 0) + n(o, "total");
    return Object.entries(m).sort((a, b) => b[1] - a[1]);
  }, [paidOrders]);
  const topMax = Math.max(1, ...bySeller.map((x) => x[1]));
  const byStatus = STATUS.map((st) => ({ st, c: orders.filter((o) => s(o, "status") === st).length }));
  const maxStatus = Math.max(1, ...byStatus.map((x) => x.c));
  const recent = orders.slice().sort((a, b) => (s(b, "placed_on") + s(b, "created_at")).localeCompare(s(a, "placed_on") + s(a, "created_at"))).slice(0, 8);

  const decide = async (p: R, status: string) => {
    setBusy(s(p, "id"));
    try {
      await app?.update("product", s(p, "id"), { status });
      setDecided((d) => [{ id: s(p, "id"), title: s(p, "title"), status }, ...d].slice(0, 5));
      setToast({ text: status === "approved" ? s(p, "title") + " is now live in the shop" : s(p, "title") + " is hidden from the shop" });
    } catch (e) { setToast({ text: e instanceof Error ? e.message : "Couldn't save that decision. Try again.", bad: true }); }
    setBusy("");
  };
  const undo = async (d: { id: string; title: string }) => {
    try { await app?.update("product", d.id, { status: "pending" }); setDecided((x) => x.filter((y) => y.id !== d.id)); setToast({ text: d.title + " is back in the queue" }); }
    catch { setToast({ text: "Couldn't undo that. Try again.", bad: true }); }
  };

  const nav = [{ id: "approvals", label: "Approvals", Icon: ShieldCheck, badge: pending.length }, { id: "sales", label: "Sales", Icon: TrendingUp, badge: 0 }];
  const fade = reduce ? {} : { initial: { opacity: 0, y: 10 }, animate: { opacity: 1, y: 0 }, exit: { opacity: 0 }, transition: { duration: 0.3, ease: EASE } };

  return (
    <div className="min-h-[100dvh] w-full text-[#2B2420] lg:grid lg:grid-cols-[240px_1fr]" style={{ background: "#FBF7F2", fontFamily: SANS }}>
      <style>{GLOBAL}</style>
      <aside className="hidden border-r border-[#EADFD0] bg-[#F6EFE6] px-4 py-6 lg:sticky lg:top-0 lg:flex lg:h-[100dvh] lg:flex-col">
        <div className="flex items-center gap-2.5 px-2"><span className="grid h-9 w-9 place-items-center rounded-full bg-[#8A5A36] text-lg text-white" style={{ fontFamily: SERIF }}>A</span><span className="text-2xl" style={{ fontFamily: SERIF }}>Atelier</span></div>
        <nav className="mt-10 space-y-1" aria-label="Console">
          {nav.map((t) => (
            <button key={t.id} onClick={() => setTab(t.id)} aria-current={tab === t.id ? "page" : undefined} className={"flex h-11 w-full items-center gap-3 rounded-xl px-3 text-[15px] font-medium transition-colors duration-200 " + (tab === t.id ? "bg-white text-[#2B2420] shadow-[0_1px_3px_rgba(60,40,20,0.1)]" : "text-[#5E5145] hover:bg-white/60")}>
              <t.Icon size={18} aria-hidden="true" />{t.label}
              {t.badge ? <span className="ml-auto rounded-full bg-[#8A5A36] px-2 py-0.5 text-[12px] tabular-nums text-white">{t.badge}</span> : null}
            </button>
          ))}
        </nav>
        <div className="mt-auto space-y-1 border-t border-[#EADFD0] pt-4">
          <button onClick={() => app?.navigate("/team")} className="flex h-11 w-full items-center gap-3 rounded-xl px-3 text-[15px] text-[#5E5145] hover:bg-white/60"><Users size={18} />Team & access</button>
          <button onClick={() => void app?.auth.signOut()} className="flex h-11 w-full items-center gap-3 rounded-xl px-3 text-[15px] text-[#5E5145] hover:bg-white/60"><LogOut size={18} />Sign out</button>
        </div>
      </aside>

      <div className="min-w-0 pb-28 lg:pb-12">
        <header className="mx-auto flex max-w-[1120px] items-center justify-between gap-4 px-4 pb-2 pt-6 sm:px-6 lg:px-10 lg:pt-10">
          <div className="min-w-0">
            <h1 className="text-[30px] leading-tight lg:text-[38px]" style={{ fontFamily: SERIF }}>{tab === "approvals" ? "New pieces to review" : "Marketplace sales"}</h1>
