                          <div className="h-2 overflow-hidden rounded-full bg-[#F3EBE0]"><motion.div initial={reduce ? false : { width: 0 }} animate={{ width: (x.c / maxStatus) * 100 + "%" }} transition={{ delay: 0.1 + i * 0.05, duration: 0.7, ease: EASE }} className="h-full rounded-full bg-[#8A9A82]" /></div>
                        </li>
