                      </thead>
                      <tbody className="divide-y divide-[#EFE6DA]">
                        {recent.map((o) => (
                          <tr key={s(o, "id")} className="align-middle">
                            <td className="px-5 py-3.5"><p className="text-[15px]" style={{ fontFamily: SERIF }}>{s(o, "product_title")}</p><p className="text-[13px] text-[#6B5D50]">{sellerName(s(o, "seller_id"))}<span className="sm:hidden"> · {buyerName(s(o, "buyer_id"))} · {day(s(o, "placed_on"))}</span></p></td>
                            <td className="hidden px-3 py-3.5 sm:table-cell">{buyerName(s(o, "buyer_id"))}</td>
                            <td className="hidden whitespace-nowrap px-3 py-3.5 tabular-nums text-[#5E5145] sm:table-cell">{day(s(o, "placed_on"))}</td>
                            <td className="hidden px-3 py-3.5 sm:table-cell"><Status st={s(o, "status")} /></td>
                            <td className="px-5 py-3.5 text-right font-medium tabular-nums">{money(n(o, "total"))}<span className="mt-1 block sm:hidden"><Status st={s(o, "status")} /></span></td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
              </motion.div>
            )}
          </AnimatePresence>
        </main>
      </div>

      <nav className="fixed inset-x-0 bottom-0 z-30 border-t border-[#EADFD0] bg-[#FBF7F2]/95 pb-[env(safe-area-inset-bottom)] backdrop-blur lg:hidden" aria-label="Console">
