              {t.badge ? <span className="absolute right-[calc(50%-24px)] top-2 grid h-5 min-w-5 place-items-center rounded-full bg-[#8A5A36] px-1 text-[11px] font-semibold text-white">{t.badge}</span> : null}
            </button>
