      <AnimatePresence>
        {toast && <motion.div key={toast.text} role="status" initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} transition={{ duration: 0.25, ease: EASE }} className={"fixed bottom-20 left-1/2 z-[60] w-[calc(100%-32px)] max-w-[420px] -translate-x-1/2 rounded-2xl px-5 py-3 text-[14px] text-white shadow-[0_12px_28px_-12px_rgba(43,36,32,0.6)] lg:bottom-8 " + (toast.bad ? "bg-[#8C3A25]" : "bg-[#2B2420]")}>{toast.text}</motion.div>}
      </AnimatePresence>
    </div>
  );
}

import { useEffect, useMemo, useState } from "react";
import { motion, useReducedMotion } from "motion/react";
import { Package, Check, CreditCard, Truck, Home, LogOut, LayoutGrid, MapPin, RefreshCw } from "lucide-react";
import type { AppHandle } from "@app/kit/primitives";

type R = Record<string, unknown>;
type Props = { app?: AppHandle };

const SERIF = "'Iowan Old Style','Palatino Linotype',Palatino,'Book Antiqua',Georgia,serif";
const SANS = "ui-sans-serif,system-ui,-apple-system,'Segoe UI',sans-serif";
const EASE = [0.22, 1, 0.36, 1] as const;
const GLOBAL = "body{transition-timing-function:cubic-bezier(0.22,1,0.36,1)}::selection{background:#EAD9C6;color:#2B2420}";
const LIFT = "shadow-[0_1px_2px_rgba(60,40,20,0.05),0_12px_28px_-18px_rgba(60,40,20,0.35)]";
const BTN = "inline-flex h-12 items-center justify-center gap-2 rounded-full bg-[#8A5A36] px-6 text-[15px] font-medium text-white transition-colors duration-200 hover:bg-[#774C2C] focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#8A5A36]";
const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

const s = (r: R | undefined, k: string): string => (r && r[k] != null ? String(r[k]) : "");
const n = (r: R | undefined, k: string): number => (r ? Number(r[k]) || 0 : 0);
const money = (v: number) => "$" + v.toLocaleString("en-US", { minimumFractionDigits: v % 1 ? 2 : 0, maximumFractionDigits: 2 });
const cap = (t: string) => t.charAt(0).toUpperCase() + t.slice(1);
const day = (iso: string, year: string) => {
  const d = iso.slice(0, 10).split("-");
  if (d.length < 3) return "";
  const out = Number(d[2]) + " " + (MONTHS[Number(d[1]) - 1] || "");
  return year && d[0] !== year ? out + " " + d[0] : out;
};

const STEPS = [
  { key: "placed", label: "Placed", Icon: Check },
  { key: "paid", label: "Paid", Icon: CreditCard },
  { key: "shipped", label: "Shipped", Icon: Truck },
  { key: "delivered", label: "Delivered", Icon: Home },
];
const COPY: Record<string, string> = {
  placed: "Waiting for your payment to clear",
  paid: "Paid. The maker is wrapping it up",
  shipped: "On its way to you",
  delivered: "Delivered. Enjoy it",
};

function Timeline({ status }: { status: string }) {
  const reduce = useReducedMotion();
  const idx = Math.max(0, STEPS.findIndex((x) => x.key === status));
  return (
    <ol className="relative mt-5 grid grid-cols-4" aria-label={"Order status: " + cap(status)}>
      <span className="absolute left-[12.5%] right-[12.5%] top-[15px] h-[2px] bg-[#EFE6DA]" aria-hidden="true" />
      <motion.span aria-hidden="true" className="absolute left-[12.5%] top-[15px] h-[2px] bg-[#B5835A]" initial={reduce ? false : { width: 0 }} animate={{ width: (idx / 3) * 75 + "%" }} transition={{ duration: 0.8, ease: EASE, delay: 0.15 }} />
      {STEPS.map((st, i) => {
        const on = i <= idx;
        return (
          <li key={st.key} className="relative flex flex-col items-center gap-1.5" aria-current={i === idx ? "step" : undefined}>
            <span className={"grid h-8 w-8 place-items-center rounded-full border " + (on ? "border-transparent bg-[#8A5A36] text-white" : "border-[#E3D6C4] bg-white text-[#75675A]")}><st.Icon size={14} aria-hidden="true" /></span>
            <span className={"text-[12px] " + (on ? "font-medium text-[#2B2420]" : "text-[#6B5D50]")}>{st.label}</span>
          </li>
        );
      })}
    </ol>
  );
}

export default function MyOrders({ app }: Props) {
  const reduce = useReducedMotion();
  const [year, setYear] = useState("");
  const [tab, setTab] = useState("active");
  const [failed, setFailed] = useState(false);
  const [retry, setRetry] = useState(0);
  useEffect(() => { setYear(String(new Date().getFullYear())); }, []);
  useEffect(() => {
    if (!app) return;
    let live = true;
    setFailed(false);
    app.query("order", { limit: 1 }).catch(() => { if (live) setFailed(true); });
    return () => { live = false; };
  }, [app, retry]);

  const orders = (app?.rows("order") ?? []) as R[];
  const products = (app?.rows("product") ?? []) as R[];
  const sellers = (app?.rows("seller") ?? []) as R[];
  const loading = app?.loading("order") ?? false;
  const photoOf = (id: string) => s(products.find((p) => s(p, "id") === id), "photo");
  const shopOf = (id: string) => sellers.find((x) => s(x, "id") === id);
  const sorted = useMemo(() => orders.slice().sort((a, b) => (s(b, "placed_on") + s(b, "created_at")).localeCompare(s(a, "placed_on") + s(a, "created_at"))), [orders]);
  const active = sorted.filter((o) => s(o, "status") !== "delivered");
  const past = sorted.filter((o) => s(o, "status") === "delivered");
  const shown = tab === "active" ? active : past;
  const spent = sorted.reduce((a, o) => a + n(o, "total"), 0);
  const firstName = (app?.user.name || "").split(" ")[0];

  return (
    <div className="min-h-[100dvh] w-full pb-28 text-[#2B2420] lg:pb-16" style={{ background: "#FBF7F2", fontFamily: SANS }}>
      <style>{GLOBAL}</style>
      <header className="sticky top-0 z-30 border-b border-[#EADFD0] bg-[#FBF7F2]/95 backdrop-blur">
        <div className="mx-auto flex h-16 max-w-[1240px] items-center gap-4 px-4 lg:px-8">
          <button onClick={() => app?.navigate("/shop")} className="flex min-h-[44px] items-center gap-2.5" aria-label="Atelier home">
            <span className="grid h-9 w-9 place-items-center rounded-full bg-[#8A5A36] text-lg text-white" style={{ fontFamily: SERIF }}>A</span>
            <span className="text-2xl tracking-tight" style={{ fontFamily: SERIF }}>Atelier</span>
          </button>
          <nav className="ml-6 hidden items-center gap-1 lg:flex" aria-label="Main">
            <button onClick={() => app?.navigate("/shop")} className="h-10 rounded-full px-4 text-[14px] font-medium text-[#6B5D50] hover:text-[#2B2420]">Shop</button>
            <button aria-current="page" className="h-10 rounded-full bg-[#F3EBE0] px-4 text-[14px] font-medium text-[#2B2420]">My orders</button>
          </nav>
          <button onClick={() => void app?.auth.signOut()} aria-label="Sign out" className="ml-auto grid h-11 w-11 place-items-center rounded-full border border-[#E8DDCF] bg-white text-[#6B5D50] hover:border-[#B5835A]"><LogOut size={18} /></button>
        </div>
      </header>

      <main className="mx-auto max-w-[1240px] px-4 pt-8 lg:px-8 lg:pt-12">
        <h1 className="text-[40px] leading-tight lg:text-[52px]" style={{ fontFamily: SERIF }}>{firstName ? firstName + "’s orders" : "Your orders"}</h1>
        <p className="mt-1 text-[15px] text-[#6B5D50]">
          {sorted.length ? sorted.length + (sorted.length === 1 ? " order" : " orders") + " · " + money(spent) + " spent with independent makers" : "Follow each piece from the maker’s bench to your door."}
        </p>

        {sorted.length > 0 && (
          <div className="mt-6 inline-flex rounded-full bg-[#F3EBE0] p-1" role="tablist" aria-label="Order status">
            {[{ id: "active", label: "On the way", k: active.length }, { id: "past", label: "Delivered", k: past.length }].map((t) => (
              <button key={t.id} role="tab" aria-selected={tab === t.id} onClick={() => setTab(t.id)} className={"h-11 rounded-full px-5 text-[14px] font-medium transition-colors duration-200 " + (tab === t.id ? "bg-white text-[#2B2420] shadow-[0_1px_3px_rgba(60,40,20,0.12)]" : "text-[#5E5145]")}>
                {t.label} <span className="tabular-nums text-[#6B5D50]">{t.k}</span>
              </button>
            ))}
          </div>
        )}

        {failed ? (
          <div className="mt-8 rounded-2xl border border-[#E3D6C4] bg-white px-6 py-14 text-center" role="alert">
            <p className="text-[24px]" style={{ fontFamily: SERIF }}>Your orders didn’t load</p>
            <p className="mt-1 text-[15px] text-[#6B5D50]">Check your connection, then try again.</p>
            <button onClick={() => setRetry((r) => r + 1)} className={BTN + " mt-6"}><RefreshCw size={16} />Try again</button>
          </div>
        ) : loading && !sorted.length ? (
          <div className="mt-8 grid gap-5 lg:grid-cols-2" aria-busy="true" aria-label="Loading orders">{[0, 1, 2, 3].map((i) => <div key={i} className="h-56 animate-pulse rounded-2xl bg-[#EFE6DA]" />)}</div>
        ) : sorted.length === 0 ? (
          <div className="mt-8 rounded-2xl border border-dashed border-[#D9CBB9] px-6 py-16 text-center">
            <Package className="mx-auto text-[#8A5A36]" size={30} aria-hidden="true" />
            <p className="mt-4 text-[24px]" style={{ fontFamily: SERIF }}>No orders yet</p>
            <p className="mx-auto mt-1 max-w-[40ch] text-[15px] text-[#6B5D50]">When you buy something, you can follow it here from the maker’s bench to your door.</p>
            <button onClick={() => app?.navigate("/shop")} className={BTN + " mt-6"}>Browse the collection</button>
          </div>
        ) : shown.length === 0 ? (
          <div className="mt-8 rounded-2xl border border-dashed border-[#D9CBB9] px-6 py-12 text-center">
            <p className="text-[22px]" style={{ fontFamily: SERIF }}>{tab === "active" ? "Nothing on the way right now" : "Nothing delivered yet"}</p>
            <p className="mt-1 text-[15px] text-[#6B5D50]">{tab === "active" ? "Everything you ordered has arrived." : "Orders move here once they reach you."}</p>
          </div>
        ) : (
          <div className="mt-6 grid gap-5 lg:grid-cols-2">
            {shown.map((o, i) => {
              const st = s(o, "status");
              const shop = shopOf(s(o, "seller_id"));
              return (
                <motion.article key={s(o, "id")} initial={reduce ? false : { opacity: 0, y: 14 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: Math.min(i, 8) * 0.05, duration: 0.45, ease: EASE }} className={"rounded-2xl bg-white p-5 " + LIFT}>
                  <div className="flex gap-4">
                    <div className="relative h-24 w-24 shrink-0 overflow-hidden rounded-xl bg-[#EFE6DA]">
                      {photoOf(s(o, "product_id")) ? <img src={photoOf(s(o, "product_id"))} alt={s(o, "product_title")} loading="lazy" className="absolute inset-0 h-full w-full object-cover" /> : null}
                    </div>
                    <div className="min-w-0 flex-1">
                      <div className="flex items-start justify-between gap-3">
                        <h2 className="text-[19px] leading-tight" style={{ fontFamily: SERIF }}>{s(o, "product_title")}</h2>
                        <span className="shrink-0 text-[16px] font-medium tabular-nums">{money(n(o, "total"))}</span>
                      </div>
                      <p className="mt-1 text-[14px] text-[#6B5D50]">{s(shop, "shop_name") || "Maker"} · {n(o, "quantity") > 1 ? n(o, "quantity") + " pieces" : "1 piece"} · Ordered {day(s(o, "placed_on"), year)}</p>
                      <p className="mt-2 text-[14px] font-medium text-[#3D332C]">{COPY[st] || cap(st)}</p>
                    </div>
                  </div>
                  <Timeline status={st} />
                  {s(o, "ship_to") && <p className="mt-4 flex items-center gap-1.5 border-t border-[#EFE6DA] pt-3 text-[13px] text-[#6B5D50]"><MapPin size={14} aria-hidden="true" />{s(o, "ship_to")}</p>}
                </motion.article>
              );
            })}
          </div>
        )}
      </main>

      <nav className="fixed inset-x-0 bottom-0 z-40 border-t border-[#EADFD0] bg-[#FBF7F2]/95 pb-[env(safe-area-inset-bottom)] backdrop-blur lg:hidden" aria-label="Main">
        <div className="mx-auto flex max-w-md">
          <button onClick={() => app?.navigate("/shop")} className="flex h-16 flex-1 flex-col items-center justify-center gap-1 text-[12px] font-medium text-[#6B5D50]"><LayoutGrid size={20} aria-hidden="true" />Shop</button>
          <button aria-current="page" className="flex h-16 flex-1 flex-col items-center justify-center gap-1 text-[12px] font-medium text-[#8A5A36]"><Package size={20} aria-hidden="true" />Orders</button>
        </div>
      </nav>
    </div>
  );
}

